import sys
sys.setrecursionlimit(2000000)

def generate(rng, n):
    if n <= 0:
        return [None]
    vals = [rng.randint(-1000, 1000) for _ in range(n)]
    root = TreeNode(vals[0])
    open_slots = [root]
    for i in range(1, n):
        node = TreeNode(vals[i])
        parent = rng.choice(open_slots)
        if parent.left is None and parent.right is None:
            if rng.random() < 0.5:
                parent.left = node
            else:
                parent.right = node
        elif parent.left is None:
            parent.left = node
            open_slots.remove(parent)
        else:
            parent.right = node
            open_slots.remove(parent)
        open_slots.append(node)
    return [root]

def generate_worst(rng, n):
    if n <= 0:
        return [None]
    nodes = [TreeNode(rng.randint(-1000, 1000)) for _ in range(n)]
    for i in range(n):
        left_idx = 2 * i + 1
        right_idx = 2 * i + 2
        if left_idx < n:
            nodes[i].left = nodes[left_idx]
        if right_idx < n:
            nodes[i].right = nodes[right_idx]
    return [nodes[0]]

